{'code': "from qgis.utils import plugins
p = plugins.get('geo_userfunc')
acts = []
for objname in ('actions','action','actionList'):
    v = getattr(p, objname, None)
    if v is None: continue
    if isinstance(v, (list, tuple)):
        for a in v:
            try: acts.append({'obj':objname,'text':a.text(),'enabled':a.isEnabled(),'name':a.objectName()})
            except Exception: pass
    else:
        try: acts.append({'obj':objname,'text':v.text(),'enabled':v.isEnabled(),'name':v.objectName()})
        except Exception: pass
result = {'has_run': hasattr(p,'run'), 'actions': acts, 'attrs': [a for a in dir(p) if 'act' in a.lower() or a=='run']}"}

{'code': "from qgis.utils import plugins
